import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";import"./chunks/assets.CGKUPeQw.js";var i=JSON.parse(`{"title":"AireForms Release Notes — 2019","description":"","frontmatter":{},"headers":[],"relativePath":"aireblock-releases/AireForms/aireforms-2019.md","filePath":"aireblock-releases/AireForms/aireforms-2019.md","lastUpdated":1786565768000}`),a={name:`aireblock-releases/AireForms/aireforms-2019.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="aireforms-release-notes-—-2019" tabindex="-1"><span class="fsc-product"><img src="/aireforms-icon.png"> AireForms Release Notes — 2019</span> <a class="header-anchor" href="#aireforms-release-notes-—-2019" aria-label="Permalink to “AireForms Release Notes — 2019”">​</a></h1><p>This page contains the AireForms releases published during 2019.</p><h2 id="version-4-13-2-—-digital-reception-styling" tabindex="-1">Version 4.13.2 — Digital Reception Styling <a class="header-anchor" href="#version-4-13-2-—-digital-reception-styling" aria-label="Permalink to “Version 4.13.2 — Digital Reception Styling”">​</a></h2><blockquote><p><strong>Release Date:</strong> November 25, 2019</p></blockquote><h3 id="⚡-improvements" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improved CSS for the digital reception tool</li></ul><h2 id="version-4-13-1-—-form-styling-usability-fixes" tabindex="-1">Version 4.13.1 — Form Styling &amp; Usability Fixes <a class="header-anchor" href="#version-4-13-1-—-form-styling-usability-fixes" aria-label="Permalink to “Version 4.13.1 — Form Styling &amp; Usability Fixes”">​</a></h2><blockquote><p><strong>Release Date:</strong> November 21, 2019</p></blockquote><h3 id="⚡-improvements-1" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-1" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improved checkbox and radio button styling for wrapped text</li><li>Improved Next and Previous buttons in the Wizard layout</li></ul><h3 id="🐞-bug-fixes" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed excessive radio button and checkbox spacing on clinician-facing forms</li><li>Fixed Scribble control button text alignment</li><li>Fixed very long single words overflowing their container in read view</li><li>Fixed default stop condition text displaying as <code>null</code></li><li>Fixed selected item colour for rich text select in the GDS theme</li><li>Fixed Scribble control allowing undo beyond the edit stack</li></ul><h2 id="version-4-12-2-—-autosave-submit-fix" tabindex="-1">Version 4.12.2 — Autosave &amp; Submit Fix <a class="header-anchor" href="#version-4-12-2-—-autosave-submit-fix" aria-label="Permalink to “Version 4.12.2 — Autosave &amp; Submit Fix”">​</a></h2><blockquote><p><strong>Release Date:</strong> October 23, 2019</p></blockquote><h3 id="🐞-bug-fixes-1" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-1" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Resolved race condition between autosave and submit</li></ul><h2 id="version-4-12-1-—-rich-text-select-accordion" tabindex="-1">Version 4.12.1 — Rich Text Select Accordion <a class="header-anchor" href="#version-4-12-1-—-rich-text-select-accordion" aria-label="Permalink to “Version 4.12.1 — Rich Text Select Accordion”">​</a></h2><blockquote><p><strong>Release Date:</strong> October 21, 2019</p></blockquote><h3 id="✨-new-features" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added rich text select as an accordion control variation</li></ul><h3 id="⚡-improvements-2" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-2" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improved rich text select styling</li><li>Improved Master Child styling</li><li>Accordion click area is now limited to the header label</li></ul><h3 id="🐞-bug-fixes-2" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-2" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed split date controls not updating when their value was changed by a calculation</li><li>Fixed select control <code>displayName</code> not updating when its value was changed by a calculation</li><li>Fixed stop condition dialog not displaying on boolean buttons with a stop condition on <code>No</code></li></ul><h2 id="version-4-11-0-—-tokenisation-xpath-improvements" tabindex="-1">Version 4.11.0 — Tokenisation &amp; XPath Improvements <a class="header-anchor" href="#version-4-11-0-—-tokenisation-xpath-improvements" aria-label="Permalink to “Version 4.11.0 — Tokenisation &amp; XPath Improvements”">​</a></h2><blockquote><p><strong>Release Date:</strong> October 1, 2019</p></blockquote><h3 id="✨-new-features-1" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-1" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Tokenisation service Get Instance Data API now supports XML as well as JSON</li><li>Added support for the <code>days-from-date()</code> function</li><li>Added support for the <code>replace()</code> function</li><li>Image Upload Control now supports low-fidelity images by default</li></ul><h3 id="⚡-improvements-3" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-3" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Suppressed the <code>model-only</code> view option as it is not currently supported</li></ul><h3 id="🐞-bug-fixes-3" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-3" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Resolved cross-building-block skip logic errors in read view</li><li>Fixed ampersands in labels appearing as their escape code</li><li>Fixed minor styling issue for radio buttons without labels</li><li>Fixed explanatory text highlight styling not being applied</li></ul><h2 id="version-4-10-0-—-delivery-channels-annotated-images" tabindex="-1">Version 4.10.0 — Delivery Channels &amp; Annotated Images <a class="header-anchor" href="#version-4-10-0-—-delivery-channels-annotated-images" aria-label="Permalink to “Version 4.10.0 — Delivery Channels &amp; Annotated Images”">​</a></h2><blockquote><p><strong>Release Date:</strong> August 14, 2019</p></blockquote><h3 id="✨-new-features-2" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-2" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Extended delivery channels to support data, PDF Base64 and tokenised key values</li><li>Added a <code>success</code> message level alongside default, info, warn and error</li><li>Added Annotated Image Control</li></ul><h3 id="⚡-improvements-4" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-4" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improved error handling for misconfigured cross-building-block rules</li><li>Improved look and feel of the tile-based form launching page</li><li>Improved handling of SMSP integration when a patient is not found</li></ul><h3 id="🐞-bug-fixes-4" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-4" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed CSV mapper issue when a form contained a multi-select with no value</li></ul><h2 id="version-4-9-1-—-repeat-loading-fix" tabindex="-1">Version 4.9.1 — Repeat Loading Fix <a class="header-anchor" href="#version-4-9-1-—-repeat-loading-fix" aria-label="Permalink to “Version 4.9.1 — Repeat Loading Fix”">​</a></h2><blockquote><p><strong>Release Date:</strong> July 29, 2019</p></blockquote><h3 id="🐞-bug-fixes-5" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-5" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Resolved issue where a form would not load when a repeat had no default iteration</li></ul><h2 id="version-4-9-0-—-fax-tokenisation-scribble-control" tabindex="-1">Version 4.9.0 — Fax, Tokenisation &amp; Scribble Control <a class="header-anchor" href="#version-4-9-0-—-fax-tokenisation-scribble-control" aria-label="Permalink to “Version 4.9.0 — Fax, Tokenisation &amp; Scribble Control”">​</a></h2><blockquote><p><strong>Release Date:</strong> July 17, 2019</p></blockquote><h3 id="✨-new-features-3" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-3" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added fax deliverer</li><li>Added Tokenisation Service Get Instance Data API and Create Tokenized Instance API</li><li>Added free-text Scribble control</li><li>Added customisable stop condition text per item in an itemset</li><li>Added Select with description text</li><li>Added ability to navigate the client to another page after form submission based on form data</li><li>Added tile-based form launching page</li><li>Added XPath function to validate NHS numbers</li><li>Added an <code>Age In Years</code> helper function</li></ul><h3 id="⚡-improvements-5" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-5" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Migrated tooltips from <code>react-tippy</code> to <code>tippy.js-react</code></li></ul><h3 id="🐞-bug-fixes-6" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-6" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed previewing a building block containing a cross-instance dollar reference</li><li>Fixed Slider control reset highlighting</li><li>Fixed Lazy Select not showing options initially</li></ul><h2 id="version-4-8-1-—-dollar-notation-fix" tabindex="-1">Version 4.8.1 — Dollar Notation Fix <a class="header-anchor" href="#version-4-8-1-—-dollar-notation-fix" aria-label="Permalink to “Version 4.8.1 — Dollar Notation Fix”">​</a></h2><blockquote><p><strong>Release Date:</strong> May 31, 2019</p></blockquote><h3 id="🐞-bug-fixes-7" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-7" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed Dollar notation resolver failing when controls have similar names</li></ul><h2 id="version-4-8-0-—-date-time-reference-data-improvements" tabindex="-1">Version 4.8.0 — Date/Time &amp; Reference Data Improvements <a class="header-anchor" href="#version-4-8-0-—-date-time-reference-data-improvements" aria-label="Permalink to “Version 4.8.0 — Date/Time &amp; Reference Data Improvements”">​</a></h2><blockquote><p><strong>Release Date:</strong> May 24, 2019</p></blockquote><h3 id="✨-new-features-4" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-4" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added combined date/time control stored as a single date-time data field</li><li>Added stable IDs to elements to aid automated testing</li><li>Added ability to customise the text shown when no items exist within a repeated grid</li><li>Added support for customer-specific pre-population types, such as admission</li><li>Added ability to configure reference data filter groups through management admin screens</li><li>Added XPath filtering support to Lazy Select</li><li>Extended the User plugin to support customer-specific key-value pairs for the logged-in user</li></ul><h3 id="⚡-improvements-6" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-6" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improved XPath error reporting</li></ul><h3 id="🐞-bug-fixes-8" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-8" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed scaling issue for static images</li></ul><h2 id="version-4-7-0-—-designer-clinician-view-improvements" tabindex="-1">Version 4.7.0 — Designer &amp; Clinician View Improvements <a class="header-anchor" href="#version-4-7-0-—-designer-clinician-view-improvements" aria-label="Permalink to “Version 4.7.0 — Designer &amp; Clinician View Improvements”">​</a></h2><blockquote><p><strong>Release Date:</strong> April 26, 2019</p></blockquote><h3 id="✨-new-features-5" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-5" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Allowed mathematical XPath functions to be used through the Designer UI</li><li>Added email body templating following Single Pass form submission</li><li>Added support for returning only the last completed form version for read and PDF views</li><li>Added facility to toggle footer and patient banner visibility in read view</li></ul><h3 id="⚡-improvements-7" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-7" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Autocomplete and Dynamic Data Dropdown controls now search the value as well as the label</li><li>Improved styling for the clinician form read view</li><li>PDF footer now includes the data submission date for clinician forms</li></ul><h2 id="version-4-6-0-—-autosuggest-reference-data" tabindex="-1">Version 4.6.0 — Autosuggest Reference Data <a class="header-anchor" href="#version-4-6-0-—-autosuggest-reference-data" aria-label="Permalink to “Version 4.6.0 — Autosuggest Reference Data”">​</a></h2><blockquote><p><strong>Release Date:</strong> March 25, 2019</p></blockquote><h3 id="✨-new-features-6" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-6" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added autosuggest reference data lookup</li><li>Added basic UI for form designers to specify building block relevance</li></ul><h3 id="⚡-improvements-8" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-8" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Test submissions for CSV/XML now clearly indicate that test data is being used</li><li>Optimised server-side form loading performance through Dollar notation resolver improvements</li><li>First validation error is now scrolled into view</li><li>Updated development form warning text</li></ul><h2 id="version-4-5-0-—-csv-export-slider-control" tabindex="-1">Version 4.5.0 — CSV Export &amp; Slider Control <a class="header-anchor" href="#version-4-5-0-—-csv-export-slider-control" aria-label="Permalink to “Version 4.5.0 — CSV Export &amp; Slider Control”">​</a></h2><blockquote><p><strong>Release Date:</strong> February 4, 2019</p></blockquote><h3 id="✨-new-features-7" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-7" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added CSV export support</li><li>Added Slider control</li><li>Added support for plugins with library dependencies</li></ul><h3 id="⚡-improvements-9" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-9" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Optimised <code>GetFormForKey</code> in FormRepository</li><li>Made it clearer to service users and recipients when Single Pass forms are not flagged as production</li><li>XPath issues are now surfaced to users in Preview Mode</li><li>Refactored persistence layer to save building blocks with instance state</li></ul><h2 id="version-4-4-0-—-clinician-form-pdf-view-configuration" tabindex="-1">Version 4.4.0 — Clinician Form &amp; PDF View Configuration <a class="header-anchor" href="#version-4-4-0-—-clinician-form-pdf-view-configuration" aria-label="Permalink to “Version 4.4.0 — Clinician Form &amp; PDF View Configuration”">​</a></h2><blockquote><p><strong>Release Date:</strong> January 14, 2019</p></blockquote><h3 id="✨-new-features-8" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-8" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added option to hide a control from the edit view of a form</li><li>Made the patient banner optional in clinician forms</li><li>Added support for custom composite PDF views, allowing a view to contain a subset of available building blocks</li></ul><h3 id="⚡-improvements-10" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-10" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improved missing Reference Data behaviour</li></ul>`,88)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};